from reproduce import project_root,sha256

LOG=logging.getLogger("h3c_final_reports")


def write(root:Path) -> dict[str,Any]:
    """Redacta documentos canónicos y registra hashes sin alterar fuentes históricas."""
    report=root/"reports/MatGPT/MatGPT_H3C_Final"
    script=root/"scripts/MatGPT/MatGPT_H3C_Final"
    if json.loads((report/"analysis/manifest.json").read_text())["status"]!="PASS":
        raise ValueError("Análisis incompleto")
    rep=json.loads((report/"reproduction/reproduction_manifest.json").read_text())
    summary=pd.read_csv(report/"analysis/summary_by_seed.csv").groupby("model").mean(numeric_only=True)
    boot=pd.read_csv(report/"analysis/paired_bootstrap.csv")
    emb=pd.read_csv(report/"analysis/embedding_summary.csv")
    bins=pd.read_csv(report/"analysis/delta_bins.csv")
    old_hist=pd.read_csv(report/"analysis/fold_seed_metrics_historical_1mev.csv")
    lock=script/"h3c_architecture_lock.yaml"
    p=summary.loc["pretrained"];r=summary.loc["random"];c=summary.loc["composition"]
    def ci(other:str,metric:str,scale:float=1.) -> str:
        """Formatea diferencia pareada preentrenado menos control con IC por fórmula."""
        row=boot[(boot.comparison==f"pretrained-minus-{other}")&(boot.metric==metric)].iloc[0]
        return f"{row.mean_difference*scale:+.2f} [{row.ci_low*scale:+.2f}, {row.ci_high*scale:+.2f}]"
    src="`scripts/MatGPT/MatGPT_frozen_3/hybrid_ridge_mlp8/`"
    caveat="[LIMITACIÓN] El código histórico conserva rutas internas anteriores a una reorganización del repositorio. La reproducción de solo lectura usa rutas actuales explícitas y recarga los checkpoints originales; no modifica el código ni los pesos históricos. Los resultados de desarrollo no son una validación externa ciega.\n\n"
    architecture=f"""# Auditoría de arquitectura H3-C\n\n[HECHO VERIFICADO] La implementación histórica está en {src}, principalmente `hybrid_predictor.py`, `run_cross_validation.py`, `common.py` y `config.yaml`. El modelo es **residual con dos ramas paralelas**. Ridge no alimenta a la MLP8.\n\n[HECHO VERIFICADO] El extractor es MatGPT incondicional preentrenado, 12 bloques, 12 cabezas, dimensión 768, vocabulario 172 y contexto 442. Checkpoint SHA-256: `{rep['source_hashes'].get('models/MatGPT-source/mat-concat/mat-uncond/weights/transformer_property_0.pth', rep['source_hashes'].get('Alternative2/models/MatGPT-source/mat-concat/mat-uncond/weights/transformer_property_0.pth'))}`. El cache de 210 estructuras lleva hash `{rep['source_hashes'].get('reports/MatGPT/MatGPT_frozen_3/run_20261023_v2/features_cache/layer_features.npz', rep['source_hashes'].get('Alternative2/reports/MatGPT/MatGPT_frozen_3/run_20261023_v2/features_cache/layer_features.npz'))}`. Se leen cadenas SLICES archivadas; `<start>`=155, `<end>`=156 y `<pad>`=157. No hubo truncamiento en el cache auditado; la posición de `<end>` y padding se validaron en su manifiesto. El Transformer se mantuvo congelado.\n\n[HECHO VERIFICADO] **Ridge:** `L03_MEAN` es el promedio de estados brutos del bloque 3 sobre tokens SLICES válidos, antes de `ln_f`, por estructura. Se promedian luego los tres embeddings de la fórmula. `StandardScaler` y `Ridge` (`lsqr`, tolerancia 1e−8, intercepto) predicen la media DFT por fórmula en eV/átomo. Alpha se eligió por error de validación interna de la media, entre `[0.01, 0.1, 1, 10, 100, 1000]`; selección por pliegue: `{rep['ridge_alphas_by_fold']}`. Ridge se reajustó con las 56 fórmulas de entrenamiento externo. Tiene 768 coeficientes y un intercepto por pliegue.\n\n[HECHO VERIFICADO] **MLP8:** `FINAL_END` es el estado de `<end>` tras `ln_f`, antes de la cabeza generativa. Capas `Linear(768,8) → GELU → Dropout(0.1) → Linear(8,1)`, sin normalización entrenable; **6 161 parámetros**. La salida cruda de cada triplete se centra restando su media. La etiqueta es el residuo de **energía DFT por átomo** respecto a la media de su fórmula, en eV/átomo. SmoothL1 beta=1 recibe predicción y etiqueta divididas por la desviación residual de entrenamiento interno. AdamW: tasa 0.001, decay 0.0001, 8 fórmulas/lote, máximo 200 épocas, paciencia 20. La época minimiza SmoothL1 completa de validación interna; no se reajusta MLP8 después.\n\n[HECHO VERIFICADO] Predicción histórica: `e_i = μ_c^Ridge + [r_i − media_j(r_j)]` en eV/átomo. Energía total `E_i = N_i e_i` y diferencias `1000(e_B − e_A)` son conversiones posteriores. H3-C **no se entrenó con energía total ni con una pérdida pairwise**. Como las salidas se centran por triplete, la predicción estructural depende de los otros dos miembros; no se debe describir como inferencia independiente por estructura.\n\n{caveat}Ver [diagrama auditado](figures/h3c_architecture.png), [fuente Mermaid](figures/h3c_architecture.mmd) y [bloqueo de configuración](../../../../scripts/MatGPT/MatGPT_H3C_Final/h3c_architecture_lock.yaml).\n"""
    reproduction=f"""# Reproducción de H3-C\n\n[HECHO VERIFICADO] Se recargaron cinco pipelines Ridge y quince checkpoints MLP8. La reproducción cubre 630 predicciones: 210 estructuras físicas, 70 fórmulas, cinco pliegues y tres semillas. El test histórico no se leyó.\n\n[RESULTADO EXPERIMENTAL] Diferencia máxima frente al CSV histórico: **{rep['max_abs_error_ev_atom']['energy_per_atom']:.2e} eV/átomo** para la predicción final, {rep['max_abs_error_ev_atom']['ridge_mean']:.2e} para Ridge y {rep['max_abs_error_ev_atom']['residual']:.2e} para residuos. Estado: **{rep['status']}**. Las discrepancias son de precisión de serialización/aritmética float32; no se forzaron métricas.\n\n[RESULTADO EXPERIMENTAL] Media sobre tres semillas: MAE E/N {p.atom_mae_mev:.2f} meV/átomo y MAE de pares firmados {p.signed_pair_mae_mev:.2f} meV/átomo, cercanos a las referencias aproximadas 183.3 y 58.8. La exactitud de mínimo por `argmin` sobre las 70 fórmulas es {100*p.gs_raw_argmin_accuracy:.1f} %, que reproduce 54.3 %. Con la regla histórica que excluye empates DFT de ≤1 meV/átomo y abstenciones del predictor, es {100*p.gs_accuracy:.1f} % sobre 67 fórmulas elegibles por semilla. El orden de pares >5 meV/átomo es {100*p.pair_accuracy_gt5:.1f} % sobre 197 pares elegibles por semilla; el protocolo histórico de 1 meV tiene otros denominadores.\n\n[HECHO VERIFICADO] Hashes de dataset, pliegues, cache, checkpoint y predicciones constan en `reproduction/reproduction_manifest.json`. Las filas recalculadas están en `reproduction/replayed_predictions.csv`. El checkpoint y los datos originales se conservaron separados.\n\n{caveat}"""
    evaluation=f"""# Evaluación de embeddings MatGPT congelados\n\n[HECHO VERIFICADO] El predictor preentrenado usa `L03_MEAN` para Ridge y `FINAL_END` para MLP8; no se actualizaron parámetros de MatGPT. Las 630 predicciones son 210 estructuras físicas repetidas por tres semillas. Las comparaciones estadísticas remuestrean 70 fórmulas después de promediar semillas dentro de cada fórmula.\n\n[RESULTADO EXPERIMENTAL] MAE de energía total derivada: {p.total_mae_ev:.3f} eV; MAE E/N: {p.atom_mae_mev:.1f} meV/átomo. Error de media composicional: {p.mean_composition_mae_mev:.1f} meV/átomo. Error de residuo intrafórmula: {p.residual_mae_mev:.1f} meV/átomo. Pendiente de paridad absoluta: {p.atom_ols_slope:.3f}; razón de dispersión absoluta: {p.atom_std_ratio:.3f}. Pendiente residual: {p.residual_ols_slope:.3f}; razón residual: {p.residual_std_ratio:.3f}.\n\n[RESULTADO EXPERIMENTAL] El MAE de pares firmados es {p.signed_pair_mae_mev:.1f} meV/átomo; predecir ΔE=0 da {p.zero_pair_mae_mev:.1f}. La mejora media de {p.zero_pair_mae_mev-p.signed_pair_mae_mev:.1f} meV/átomo es pequeña respecto a la dispersión entre fórmulas. Estado fundamental elegible: {100*p.gs_accuracy:.1f} %; orden de pares elegibles >5: {100*p.pair_accuracy_gt5:.1f} %. No se adjudica un mínimo al predictor de ΔE cero.\n\n[INFERENCIA] Los embeddings preentrenados permiten recuperar señal de ordenamiento sobre este protocolo, pero la precisión de separaciones energéticas pequeñas no queda demostrada por el ranking. Una cabeza fija no mide toda la información del Transformer.\n\n{caveat}"""
    random=f"""# Preentrenamiento frente a backbone aleatorio congelado\n\n[HECHO VERIFICADO] Los tres controles aleatorios usan el mismo MatGPT oficial, tokenizer, 768 dimensiones, dos poolings H3-C, folds y arquitectura de regresor. Se inicializaron con semilla + 500000; sus hashes exactos están en `random_initialization_lock.json`. Ningún backbone aleatorio recibió gradientes. No se reutilizaron las métricas del antiguo E2, que tenía otra cabeza.\n\n[RESULTADO EXPERIMENTAL] Preentrenado vs aleatorio: MAE E/N {p.atom_mae_mev:.1f} vs {r.atom_mae_mev:.1f} meV/átomo; MAE residual {p.residual_mae_mev:.1f} vs {r.residual_mae_mev:.1f}; MAE pares {p.signed_pair_mae_mev:.1f} vs {r.signed_pair_mae_mev:.1f}. Diferencia apareada preentrenado menos aleatorio: MAE absoluto {ci('random','absolute_mae_mev_atom')} meV/átomo; MAE pares {ci('random','pair_mae_mev_atom')} meV/átomo (intervalos 95 %, bootstrap de fórmula).\n\n[RESULTADO EXPERIMENTAL] Acierto de mínimo elegible {100*p.gs_accuracy:.1f} % vs {100*r.gs_accuracy:.1f} %; diferencia apareada {ci('random','gs_correct',100)} puntos porcentuales. Orden de pares >5: {100*p.pair_accuracy_gt5:.1f} % vs {100*r.pair_accuracy_gt5:.1f} %; diferencia apareada {ci('random','pair_accuracy_gt5',100)} puntos.\n\n[INFERENCIA] En este conjunto, el preentrenamiento favorece decisiones de ranking, pero empeora el error absoluto frente al control aleatorio. La diferencia de MAE de pares tiene intervalo que incluye cero; por tanto no se demuestra mejora de precisión de ΔE. No extrapolar a otras cabezas, datos o a entrenamiento desde cero.\n\n{caveat}"""
    composition=f"""# Control de composición solamente\n\n[HECHO VERIFICADO] El vector contiene fracciones estequiométricas de 17 elementos (`Ba, Ca, Cd, Cu, Ge, Hf, Mg, Nb, Pb, S, Si, Sn, Sr, Ti, V, Zn, Zr`). Cada polimorfo de una fórmula recibe exactamente el mismo vector; no entran IDs, energías, topología ni geometría. Ridge usa el mismo grid alpha, StandardScaler, selección interna y refit histórico, con 17 entradas inevitables en vez de 768. La rama residual centrada es algebraicamente cero para tres entradas idénticas; no se le atribuye un entrenamiento útil ni ranking arbitrario.\n\n[RESULTADO EXPERIMENTAL] MAE E/N: **{c.atom_mae_mev:.1f} meV/átomo**; MAE de la media de fórmula: {c.mean_composition_mae_mev:.1f} meV/átomo; MAE residual: {c.residual_mae_mev:.1f}; MAE de pares = baseline ΔE cero = {c.signed_pair_mae_mev:.1f}. Los tres polimorfos siempre empatan.\n\n[RESULTADO EXPERIMENTAL] Diferencia H3-C preentrenado menos composición: MAE absoluto {ci('composition','absolute_mae_mev_atom')} meV/átomo; MAE de pares {ci('composition','pair_mae_mev_atom')} meV/átomo. La primera comparación favorece la fórmula; la segunda no demuestra una mejora clara de ΔE.\n\n[INFERENCIA] En estas composiciones, la química explica gran parte del nivel energético absoluto. La fórmula sola no contiene identidad de polimorfo y no permite selección estructural.\n\n{caveat}"""
    binmean=bins[bins.model=="pretrained"].groupby(["lower_mev","upper_mev"],as_index=False).agg(n=("n_pairs","mean"),mae=("mae_model_mev","mean"),zero=("mae_zero_mev","mean"),accuracy=("pair_accuracy","mean"))
    bin_lines=[]
    for row in binmean.itertuples():
        label=f"{row.lower_mev:g}–{row.upper_mev:g}" if np.isfinite(row.upper_mev) else ">100"
        acc=f"{100*row.accuracy:.1f}%" if np.isfinite(row.accuracy) else "no definido"
        bin_lines.append(f"| {label} | {int(row.n)} | {row.mae:.1f} | {row.zero:.1f} | {acc} |")
    intra=f"""# Energía intrafórmula y magnitud del gap\n\n[HECHO VERIFICADO] Para cada fórmula, `e_i = Etotal_i/N_i`; se calculan por separado las medias DFT y predicha, y los residuos `e_i − media(e_c)`. La media DFT solo entra en métricas posteriores, jamás en inferencia. Los pares se forman exclusivamente dentro de la misma fórmula.\n\n[RESULTADO EXPERIMENTAL] H3-C: error de media por fórmula {p.mean_composition_mae_mev:.1f} meV/átomo, error de residuo {p.residual_mae_mev:.1f}, MAE de pares {p.signed_pair_mae_mev:.1f}, ΔE anclado al mismo estado fundamental DFT {p.anchored_delta_mae_mev:.1f}. Pendiente residual {p.residual_ols_slope:.3f} y razón de dispersión {p.residual_std_ratio:.3f}; esto cuantifica compresión intrafórmula de la salida, no colapso del embedding.\n\n| Magnitud de ΔE DFT (meV/átomo) | Pares físicos/semilla | MAE H3-C | MAE ΔE=0 | Acierto de orden elegible |\n|---|---:|---:|---:|---:|\n{chr(10).join(bin_lines)}\n\n[HECHO VERIFICADO] El umbral de elegibilidad principal de esta auditoría es >5 meV/átomo: 197 pares por semilla. El análisis histórico de H3-C usa una tolerancia de 1 meV/átomo y otro denominador; ambas tablas se preservan en `analysis/`. Los intervalos con menos de diez pares se marcan en `delta_bins.csv`.\n\n[RESULTADO EXPERIMENTAL] Diferencia H3-C menos aleatorio en MAE de pares: {ci('random','pair_mae_mev_atom')} meV/átomo, intervalo que incluye cero. Frente a ΔE=0, la reducción media es solo {p.zero_pair_mae_mev-p.signed_pair_mae_mev:.1f} meV/átomo. No confundir cancelación de offset composicional con precisión de diferencias.\n\n{caveat}"""
    ranks=pd.read_csv(report/"analysis/rank_correlations_summary.csv")
    rank_sentences=[]
    for model,label in (("pretrained","H3-C preentrenado"),("random","MatGPT aleatorio")):
        sub=ranks[ranks.model==model]
        values="; ".join(f"semilla {int(row.seed)}: {row.spearman_mean_defined:.3f}/{row.kendall_mean_defined:.3f}" for row in sub.itertuples())
        rank_sentences.append(f"{label} (Spearman/Kendall): {values}")
    rank_paragraph=("[RESULTADO EXPERIMENTAL] En los 70 tripletes por semilla, "
                    + ". ".join(rank_sentences)
                    + ". Composición sola empata en todos los tripletes: correlaciones indefinidas. "
                      "Detalle: `analysis/rank_correlations_by_formula.csv`.\n\n")
    intra=intra.replace(caveat,rank_paragraph+caveat)
    spec="""# Especificación inmutable H3-C\n\n[HECHO VERIFICADO] El contrato científico es el archivo `h3c_architecture_lock.yaml`; cualquier cambio de extractor, pooling, ancho oculto, activación, target, normalización o selección constituye **otro experimento**. El test de arquitectura falla ante cambios de dimensiones y checkpoint.\n\n**Entradas:** SLICES estándar archivado → MatGPT incondicional congelado → `L03_MEAN` y `FINAL_END`, cada uno de 768 dimensiones. **Rama media:** promedio de tres `L03_MEAN` → StandardScaler + Ridge (768→1). **Rama residual:** tres `FINAL_END` → Linear(768,8) → GELU → Dropout(.1) → Linear(8,1) → centrado. **Suma:** energía por átomo predicha. **Postproceso:** energía total = N×e; ΔE y mínimo solo dentro de fórmula.\n\n[HECHO VERIFICADO] Ridge y MLP8 se ajustan con objetivos distintos: media de energía DFT por fórmula y residuo respecto a la media, ambos en eV/átomo. Ridge se reajusta con 56 fórmulas después de elegir alpha; MLP8 conserva el checkpoint elegido con 11 fórmulas de validación interna y se entrenó sobre 45. No hay pérdida de pares.\n\n[HIPÓTESIS] En futura fusión geométrica solo podrá cambiar la dimensión de la primera proyección que reciba nuevas características. El ancho 8, GELU, dropout, salida, pérdida y reglas de selección siguen bloqueados; cualquier aumento de parámetros de entrada deberá reportarse. No se implementa geometría aquí.\n"""
    conclusions=f"""# Conclusiones científicas H3-C\n\n[HECHO VERIFICADO] La topología exacta es Ridge paralelo a MLP8 residual; no una cadena Ridge→MLP. Checkpoints reproducidos con error máximo {rep['max_abs_error_ev_atom']['energy_per_atom']:.2e} eV/átomo. La etiqueta histórica es energía DFT por átomo.\n\n[RESULTADO EXPERIMENTAL] H3-C preentrenado: MAE absoluto {p.atom_mae_mev:.1f}, residual {p.residual_mae_mev:.1f} y de pares {p.signed_pair_mae_mev:.1f} meV/átomo. Acierto del estado fundamental elegible {100*p.gs_accuracy:.1f} % y pares >5 {100*p.pair_accuracy_gt5:.1f} %. Composición sola consigue mejor MAE absoluto ({c.atom_mae_mev:.1f}), pero produce empates en todos los tripletes.\n\n[INFERENCIA] El backbone preentrenado aporta señal para ordenar polimorfos frente al aleatorio, con diferencia apareada de {ci('random','pair_accuracy_gt5',100)} puntos porcentuales, pero el MAE de diferencias no mejora de forma concluyente ({ci('random','pair_mae_mev_atom')} meV/átomo). No hay evidencia de que H3-C agote la información disponible en MatGPT ni de que añadir geometría resolverá el error.\n\n[HIPÓTESIS] La geometría explícita podría añadir información a diferencias intrafórmula, especialmente si pares estructuralmente distintos tienen embeddings similares o gaps predichos comprimidos. Será una comparación posterior, con mismo objetivo y protocolo.\n\n[LIMITACIÓN] Los 70 grupos de desarrollo ya influyeron en decisiones históricas; los intervalos son exploratorios. No se certificó una política XC/U/correcciones homogénea por registro gga-static. El test histórico permanece cerrado.\n"""
    geometry="""# Protocolo para una futura comparación con geometría\n\n[HECHO VERIFICADO] La interfaz estable `interface.py` expone `load_inputs()` (ID físico, fórmula, N, SLICES y ambos embeddings), `predict_triplets()` y `evaluate_intraformula()`. Por defecto no entrega etiquetas DFT; estas solo se solicitan en entrenamiento o evaluación autorizada.\n\n[HIPÓTESIS] En un estudio posterior, descriptores geométricos derivados de la estructura podrán concatenarse a la rama estructural H3-C. Se conservarán los cinco pliegues, las tres semillas, los mismos targets por átomo, Ridge, anchura oculta 8, GELU, dropout .1, pérdida y regla de selección. Solo aumentará la dimensión de entrada de la primera capa y su recuento de parámetros, que deberá documentarse antes de evaluar.\n\n[LIMITACIÓN] No se han calculado ni añadido descriptores geométricos. No hay resultado de mejora geométrica en este módulo. Cualquier afirmación futura requiere validación sobre composiciones no usadas para seleccionar el diseño.\n"""
    env=f"""# Entorno fijado y límites de determinismo\n\n[HECHO VERIFICADO] Python {platform.python_version()}; PyTorch {torch.__version__}; scikit-learn {sklearn.__version__}; NumPy {np.__version__}; pandas {pd.__version__}; SciPy {scipy.__version__}; joblib {joblib.__version__}; plataforma `{platform.platform()}`. Ejecución CPU con dos threads; CUDA y MPS no se usaron. Semillas 42, 123 y 2026.\n\n[HECHO VERIFICADO] Checkpoint MatGPT SHA-256 `{rep['source_hashes'].get('models/MatGPT-source/mat-concat/mat-uncond/weights/transformer_property_0.pth', rep['source_hashes'].get('Alternative2/models/MatGPT-source/mat-concat/mat-uncond/weights/transformer_property_0.pth'))}`; cache de features `{rep['source_hashes'].get('reports/MatGPT/MatGPT_frozen_3/run_20261023_v2/features_cache/layer_features.npz', rep['source_hashes'].get('Alternative2/reports/MatGPT/MatGPT_frozen_3/run_20261023_v2/features_cache/layer_features.npz'))}`. Los hashes de cada Ridge y MLP8 permanecen en sus manifiestos históricos; la reproducción los carga sin sobrescribirlos.\n\n[LIMITACIÓN] Inicializadores, BLAS, serialización y orden de operaciones pueden producir diferencias float32 pequeñas entre plataformas. La tolerancia de reproducción fijada es 1e−5 eV/átomo; en este entorno se observó {rep['max_abs_error_ev_atom']['energy_per_atom']:.2e}. El lock de pesos aleatorios verifica hashes tensoriales y falla si cambia la inicialización.\n"""
    historical="""# Resumen mínimo de exploración previa\n\n[HECHO VERIFICADO] Antes del bloqueo H3-C se evaluaron Siamese B2–B5, ablaciones de pesos/pooling y sonda lineal E1/E2/E3. Sus scripts, reportes, checkpoints y resultados negativos se preservan en el archivo recuperable registrado por `cleanup_backup_manifest.json`. No se usan para seleccionar otra arquitectura.\n\n[RESULTADO EXPERIMENTAL] La sonda lineal E1 obtuvo 559.7 meV/átomo en energía absoluta y 585.5 meV/átomo en pares firmados; el baseline ΔE=0 era 60.5. Las ablaciones Siamese mostraron compensaciones entre energía absoluta y ΔE, y las salidas podían comprimirse sin demostrar colapso global de hidden states. Estos datos son contexto histórico, no reentrenamientos de esta consolidación.\n\n[INFERENCIA] H3-C se conserva como referencia supervisada reproducible por decisión del protocolo, no porque se haya demostrado óptimo entre todas las variantes.\n"""
    readme="""# MatGPT H3-C Final\n\nMódulo bloqueado para estudiar energía media por composición y diferencia entre polimorfos ABS₃ con MatGPT congelado. H3-C histórico reproducido exactamente desde sus cinco Ridge y quince MLP8.\n\n## Reproducción sin reentrenamiento\n\nDesde la raíz del proyecto, con `.venv` activo:\n\n```bash\nKMP_DUPLICATE_LIB_OK=TRUE OMP_NUM_THREADS=2 .venv/bin/python scripts/MatGPT/MatGPT_H3C_Final/reproduce.py\nKMP_DUPLICATE_LIB_OK=TRUE OMP_NUM_THREADS=2 .venv/bin/python -m unittest discover -s scripts/MatGPT/MatGPT_H3C_Final/tests -p 'test_*.py'\n```\n\nLos controles completos ya están guardados en `controls/`; sus comandos exactos y recursos por corrida figuran en los logs/JSON del módulo. El test histórico no se abre.\n\n## Lectura\n\nComenzar por `h3c_architecture_audit.md`, `h3c_reproduction_report.md` y `h3c_scientific_conclusions.md`. Figuras y diagramas verificados en `figures/`; métricas por estructura, fórmula, par y bootstrap en `analysis/`. `h3c_architecture_lock.yaml` fija las decisiones arquitectónicas. `cleanup_report.md` describe el archivo recuperable de experimentos anteriores.\n"""
    docs={"h3c_architecture_audit.md":architecture,"h3c_reproduction_report.md":reproduction,
          "h3c_frozen_embedding_evaluation.md":evaluation,"h3c_pretraining_vs_random.md":random,
          "h3c_composition_baseline.md":composition,"h3c_intraformula_energy_analysis.md":intra,
          "h3c_architecture_spec.md":spec,"h3c_scientific_conclusions.md":conclusions,
          "h3c_next_geometry_protocol.md":geometry,"h3c_environment_lock.md":env,
          "historical_exploration_summary.md":historical,"README.md":readme}
    for name,body in docs.items():
        path=report/name
        if path.exists():raise ValueError(f"Se rechaza sobrescribir informe existente: {path}")
        path.write_text(body,encoding="utf-8")
    result={"status":"PASS","reports":{name:sha256(report/name) for name in docs},
            "architecture_lock_sha256":sha256(lock),
            "reproduction_manifest_sha256":sha256(report/"reproduction/reproduction_manifest.json"),
            "analysis_manifest_sha256":sha256(report/"analysis/manifest.json"),
            "historical_test_accessed":False}
    (report/"scientific_manifest.json").write_text(json.dumps(result,indent=2,ensure_ascii=False)+"\n")
    LOG.info(json.dumps({"event":"reports_written","count":len(docs),"status":"PASS"}))
    return result


def main() -> None:
    """Carga resultados verificables y crea informes sin datos sintéticos."""
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--repo",type=Path,default=project_root())
    args=parser.parse_args()
    logging.basicConfig(level=logging.INFO,format="%(message)s")
    write(args.repo.resolve())


if __name__=="__main__":main()
